<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/core.php';require dirname(__DIR__).'/app/features.php';
$dir=sys_get_temp_dir().'/xfedi-social-'.bin2hex(random_bytes(8));mkdir($dir,0700);
putenv('XFEDI_DATA_DIR='.$dir);putenv('XFEDI_URL=https://social.example/index.php');
$checks=0;
function assertSocial(bool $ok,string $message): void {global $checks;if (!$ok) throw new RuntimeException('FAIL '.$message);$checks++;}
try {
    initDb();
    $key=openssl_pkey_new(['private_key_bits'=>2048]);openssl_pkey_export($key,$private);$public=openssl_pkey_get_details($key)['key'];
    executeSql('INSERT INTO users(id,username,name,password_hash,private_key,public_key,created_at) VALUES(1,?,?,?,?,?,?)',['alice','Alice',password_hash('fixture-password',PASSWORD_DEFAULT),$private,$public,time()]);
    $a='https://remote.example/users/bob';$b='https://third.example/users/cara';
    foreach ([$a,$b] as $id) executeSql('INSERT INTO remote_actors(id,username,name,inbox,key_id,public_key,fetched_at) VALUES(?,?,?,?,?,?,?)',[$id,basename($id),ucfirst(basename($id)),'https://'.parse_url($id,PHP_URL_HOST).'/inbox',$id.'#key',$public,time()]);
    $visuals=actorVisuals(['icon'=>[['type'=>'Image','url'=>['type'=>'Link','href'=>'https://cdn.example/avatar.webp']]],'image'=>['url'=>[['href'=>'https://cdn.example/header.avif']]]]);
    assertSocial($visuals['avatar']==='https://cdn.example/avatar.webp' && $visuals['cover']==='https://cdn.example/header.avif','avatar and header URL variants');
    assertSocial(actorVisuals(['image'=>['url'=>'http://127.0.0.1/internal']])['cover']==='','unsafe cover rejected');
    executeSql('UPDATE users SET cover=?',[str_repeat('a',32).'.png']);$before=actorObject()['image']['url'];
    executeSql('UPDATE users SET cover=?',[str_repeat('b',32).'.png']);$after=actorObject()['image']['url'];
    assertSocial($before!==$after && str_contains($after,'&v='),'local header URL changes with image replacement');
    $media=noteMedia(['type'=>'Note','attachment'=>[['type'=>'Document','mediaType'=>'image/gif','url'=>'https://cdn.example/1.gif','name'=>'Animated image'],['type'=>'Image','url'=>'https://cdn.example/2.avif'],['type'=>'Document','mediaType'=>'video/mp4','url'=>'https://cdn.example/clip.mp4'],['type'=>'Audio','url'=>'https://cdn.example/track.mp3']]]);
    assertSocial(count($media)===4 && array_column($media,'type')===['image','image','video','audio'],'gallery and video/audio extraction');
    assertSocial(noteMedia(['attachment'=>['type'=>'Document','mediaType'=>'image/webp','url'=>['type'=>'Link','href'=>'https://cdn.example/1']]])[0]['type']==='image','single attachment and Link URL');
    assertSocial(noteMedia(['image'=>'https://cdn.example/no-extension'])[0]['type']==='image','top-level image without extension');
    assertSocial(noteMedia(['attachment'=>['type'=>'Image','url'=>'javascript:alert(1)']])===[],'unsafe media rejected');
    assertSocial(quoteTarget(['quote'=>[['id'=>'https://third.example/notes/original']]])==='https://third.example/notes/original','structured quote field');
    assertSocial(quoteTarget(['quoteUri'=>'https://third.example/notes/original'])==='https://third.example/notes/original','legacy quote field');
    assertSocial(quoteTarget(['quote'=>'file:///private'])==='','invalid quote URL rejected');
    $html='<title>Fallback</title><meta property="og:title" content="An article"><meta property="og:description" content="A useful story"><meta property="og:image" content="/uploads/featured.webp"><meta property="og:site_name" content="My blog">';
    $card=parseSocialMetadata($html,'https://blog.example/story');
    assertSocial($card['image']==='https://blog.example/uploads/featured.webp' && $card['title']==='An article','Open Graph featured image');
    assertSocial(parseSocialMetadata('<meta name="twitter:image" content="https://cdn.example/card.jpg">','https://blog.example/')['image']==='https://cdn.example/card.jpg','Twitter card image');
    assertSocial(parseSocialMetadata('<meta itemprop="image" content="/schema.png">','https://blog.example/')['image']==='https://blog.example/schema.png','microdata image');
    assertSocial(parseSocialMetadata('<link rel="image_src" href="/legacy.jpg">','https://blog.example/')['image']==='https://blog.example/legacy.jpg','legacy image_src');
    assertSocial(parseSocialMetadata('<script type="application/ld+json">{"@type":"BlogPosting","image":{"url":"/structured.jpg"}}</script>','https://blog.example/')['image']==='https://blog.example/structured.jpg','JSON-LD image');
    assertSocial(parseSocialMetadata('<img class="wp-post-image attachment-post-thumbnail" src="/featured.jpg">','https://blog.example/')['image']==='https://blog.example/featured.jpg','WordPress featured image fallback');
    assertSocial(parseSocialMetadata('<meta property="og:image" content="javascript:alert(1)"><title>Safe</title>','https://blog.example/')['image']==='','unsafe social image rejected');
    assertSocial(parseSocialMetadata('<link rel="alternate" type="application/json+oembed" href="/oembed?id=1">','https://blog.example/')['oembed']==='https://blog.example/oembed?id=1','oEmbed endpoint recognized without trusting embed HTML');
    assertSocial(noteLinks(['content'=>'Read more','content_html'=>'<a href="https://blog.example/article">Read the article</a>'])===['https://blog.example/article'],'preview uses real HTML anchor URL');
    assertSocial(noteLinks(['content'=>'@bob','content_html'=>'<a class="mention" href="https://remote.example/users/bob">Bob</a>'])===[],'mentions do not become website cards');
    $profile='https://social.example/@alice';
    assertSocial(websiteEvidence('<a href="'.$profile.'">My social profile</a>','https://blog.example/',[$profile])==='profile-link','ordinary existing backlink accepted without rel-me snippet');
    assertSocial(websiteEvidence('<a href="'.$profile.'" rel="me">Me</a>','https://blog.example/',[$profile])==='rel-me','standard rel-me evidence remains supported');
    assertSocial(websiteEvidence('<title>My site</title>','https://social.example/about',[$profile])==='same-domain','same domain association');
    assertSocial(websiteEvidence('<title>Some other site</title>','https://other.example/',[$profile])==='','reachable arbitrary website is not proof');
    $state=websiteStatus(['website_verified_at'=>0,'website_reachable_at'=>time(),'website_method'=>'']);
    assertSocial(!$state['confirmed'] && str_contains($state['label'],'unconfirmed'),'reachability is visibly distinct from verification');
    $note=['type'=>'Article','id'=>'https://remote.example/notes/article','attributedTo'=>$a,'content'=>'<p>Article text <a href="https://blog.example/story">Read more</a></p>','url'=>'https://blog.example/story','to'=>[AS_PUBLIC],'published'=>nowIso(time()-30),'quote'=>['id'=>'https://third.example/notes/original'],'attachment'=>[['type'=>'Image','url'=>'https://cdn.example/1.jpg'],['type'=>'Image','url'=>'https://cdn.example/2.jpg']]];
    noteInbound($note,$a,true,true);$stored=knownPost($note['id']);
    assertSocial($stored!==null && $stored['object_type']==='Article','WordPress-style Article imported');
    assertSocial(count(json_decode($stored['media_json'],true))===2,'all gallery images persisted');
    assertSocial($stored['quote_of']==='https://third.example/notes/original','structured quote persisted');
    assertSocial(queryOne("SELECT ref FROM enrichment_jobs WHERE kind='note' AND ref=?",[$stored['quote_of']])!==null,'missing original quote queued for background fetch');
    assertSocial(queryOne("SELECT ref FROM enrichment_jobs WHERE kind='preview' AND ref='https://blog.example/story'")!==null,'featured card queued');
    queueNoteEnrichment($stored);queueNoteEnrichment($stored);
    assertSocial((int)queryOne("SELECT COUNT(*) n FROM enrichment_jobs WHERE kind='preview' AND ref='https://blog.example/story'")['n']===1,'preview work deduplicated');
    $note['attachment'][]=['type'=>'Image','url'=>'https://cdn.example/3.jpg'];noteInbound($note,$a,true,true);
    assertSocial(count(json_decode(knownPost($note['id'])['media_json'],true))===3,'unchanged timestamp can backfill media without another notification');
    executeSql('INSERT INTO follows(actor_id,follow_id,status,created_at) VALUES(?,?,?,?)',[$a,'https://social.example/follow','accepted',time()]);
    $boost=['id'=>'https://remote.example/activities/boost-1','actor'=>$a,'type'=>'Announce','object'=>$note['id'],'to'=>[AS_PUBLIC],'published'=>nowIso()];
    $actor=queryOne('SELECT * FROM remote_actors WHERE id=?',[$a]);$actor['outbox']='https://remote.example/outbox';
    $imported=importOutbox($actor,static fn($url)=>['type'=>'OrderedCollection','orderedItems'=>[$boost]]);
    assertSocial($imported===1 && queryOne('SELECT activity_id FROM boosts_remote WHERE actor_id=? AND note_id=?',[$a,$note['id']])!==null,'remote outbox Announce is imported');
    assertSocial(subscribeInstance('https://remote.example')==='remote.example','instance subscription normalizes host');
    $failed=false;try {subscribeInstance('127.0.0.1');} catch(Throwable) {$failed=true;}
    assertSocial($failed,'unsafe instance subscription rejected');
    $fetched=[];
    $listing=[['visibility'=>'public','uri'=>$note['id'],'created_at'=>nowIso()],['visibility'=>'private','uri'=>'https://remote.example/private'],['visibility'=>'public','created_at'=>nowIso(),'account'=>['uri'=>$a],'reblog'=>['visibility'=>'public','uri'=>$note['id']]]];
    $n=importInstanceListing('remote.example',$listing,static function($id) use (&$fetched) {$fetched[]=$id;return knownPost($id);});
    assertSocial($n===2 && !in_array('https://remote.example/private',$fetched,true),'public listing fetches only public canonical candidates');
    assertSocial(queryOne('SELECT boost_actor FROM instance_posts WHERE domain=? AND note_id=?',['remote.example',$note['id']])['boost_actor']===$a,'instance feed retains boost attribution');
    executeSql('INSERT INTO posts(content,created_at,updated_at) VALUES(?,?,?)',['My post',time(),time()]);
    $_SESSION=['uid'=>1];$auth=true;$me=user();$page='home';$_GET=[];$flash=$error=$draftContent='';
    require dirname(__DIR__).'/app/view_helpers.php';ob_start();require dirname(__DIR__).'/app/views.php';$html=ob_get_clean();
    assertSocial(str_contains($html,'Delete your post') && str_contains($html,'return_page'),'delete is available directly on own timeline card');
    assertSocial(str_contains($html,'compose-editor') && str_contains($html,'class="compose-input"'),'bounded, labeled composer markup');
    assertSocial(str_contains($html,'Home</a>') && str_contains($html,'Federated</a>'),'separate timeline navigation');
    $refs=entries('federated','remote.example');assertSocial(count($refs)===1 && $refs[0]['id']===$note['id'],'instance filter is independent of account follow');
    executeSql('DELETE FROM follows');assertSocial(count(entries('home'))===1 && count(entries('federated'))===2,'home and public federation have separate sources');
    executeSql('INSERT INTO hidden_posts(note_id,created_at) VALUES(?,?)',[$note['id'],time()]);assertSocial(count(entries('federated'))===1,'remote hiding filters timelines without deleting source');
    echo "PASS $checks social presentation and instance checks\n";
} finally {foreach(glob($dir.'/*')?:[] as $file) unlink($file);rmdir($dir);}
